#include <stdio.h>

int main(void) {
    char tag[] = "STOCK";
    int len = 0;
    int left, right;
    char temp;
    while (tag[len] != '\0') {
        len++;
    }
    // 양 끝 글자를 바꾸며 가운데로 한 칸씩 다가가요.
    for (left = 0, right = len - 1; left < len; left++, right--) {
        temp = tag[left];
        tag[left] = tag[right];
        tag[right] = temp;
    }
    printf("%s", tag);
    return 0;
}

