#include <stdio.h>

// 받은 두 글자를 바꿔요.
void swap_value(char a, char b) {
    char t = a;
    a = b;
    b = t;
}

// 두 주소에 있는 글자를 바꿔요.
void swap_at(char *a, char *b) {
    char t = *a;
    *a = *b;
    *b = t;
}

// s가 가리키는 문자열을 제자리에서 뒤집어요.
void reverse(char *s) {
    char *left = s;
    char *right = s;
    while (*right != '\0') {
        right++;
    }
    right--;
    while (left < right) {
        swap_value(*left, *right);
        left++;
        right--;
    }
}

int main(void) {
    char word[] = "DRAWER";
    reverse(word);
    printf("%s %s %c", word, word + 3, *(word + 1));
    return 0;
}

